"""Hardware smoke test; it inspects PCM generated by the connected ESP32."""

import argparse
import hashlib
import queue
import struct
import threading
import time

from transport import SerialTransport


def samples(pcm: bytes) -> tuple[int, ...]:
    return struct.unpack(f"<{len(pcm) // 2}h", pcm)


def metrics(pcm: bytes) -> tuple[float, int, float]:
    values = samples(pcm)
    rms = (sum(value * value for value in values) / len(values)) ** 0.5
    peak = max(abs(value) for value in values)
    crossings = sum(a <= 0 < b for a, b in zip(values, values[1:]))
    frequency = crossings / (len(values) / 48_000)
    return rms, peak, frequency


class SmokeTest:
    def __init__(self, port: str) -> None:
        self.audio: queue.Queue[bytes] = queue.Queue(maxsize=500)
        self.statuses: list[dict] = []
        self.status_event = threading.Event()
        self.transport = SerialTransport(self.audio, self._status)
        self.transport.connect(port)
        if not self.status_event.wait(2):
            raise AssertionError("STATUS timeout")

    def _status(self, status: dict) -> None:
        self.statuses.append(status)
        self.status_event.set()

    def send(self, *commands: str) -> None:
        for command in commands:
            self.transport.send(command)

    def drain(self) -> None:
        while True:
            try:
                self.audio.get_nowait()
            except queue.Empty:
                return

    def grab(self, block_count: int) -> bytes:
        return b"".join(
            self.audio.get(timeout=0.3) for _ in range(block_count)
        )

    def settle(self, seconds: float = 0.15) -> None:
        time.sleep(seconds)
        self.drain()

    def verify_output_routing(self) -> None:
        assert self.statuses[-1]["i2sReady"] is True

        self.send("SET OUTPUT PC", "STREAM 1")
        self.settle(0.10)
        self.grab(3)

        self.send("SET OUTPUT GPIO")
        time.sleep(0.15)
        self.drain()
        time.sleep(0.08)
        assert self.audio.empty(), "GPIO mode still produced USB AUDIO packets"

        self.status_event.clear()
        self.send("HELLO")
        assert self.status_event.wait(1), "STATUS timeout in GPIO mode"
        assert self.statuses[-1]["output"] == "GPIO"
        time.sleep(0.08)
        assert self.audio.empty(), "HELLO in GPIO mode enabled USB AUDIO"

        self.send("SET OUTPUT BOTH")
        time.sleep(0.25)
        self.drain()
        self.grab(3)
        self.send("SET OUTPUT PC")
        print("OUTPUT_ROUTING", "PC/GPIO/BOTH USB behavior ok")

    def run(self) -> None:
        status = self.statuses[-1]
        print("STATUS", status)
        assert status["protocol"] == 1
        assert status["sampleRate"] == 48_000
        assert status["blockSamples"] == 480
        assert status["maxRenderUs"] < 10_000
        assert status["output"] in ("PC", "GPIO", "BOTH")
        self.verify_output_routing()

        self.send(
            "SET OUTPUT PC",
            "SET PROFILE EXTENDED",
            "SET MODE SINE1",
            "SET LFO_SHAPE TRIANGLE",
            "SET LFO_DEPTH_OCT 0",
            "SET ECHO_LEVEL 0",
            "SET MASTER 0.5",
            "SET TUNE_HZ 220",
            "SET DECAY_MS 0",
            "TRIGGER 0",
            "HOLD 0",
            "MODULATION 1",
            "RETRIGGER 0",
            "ECHO_SPIN 0",
            "ECHO_LOOP 0",
            "STREAM 1",
        )
        self.settle()
        rms, _, _ = metrics(self.grab(20))
        assert rms == 0

        self.send("TRIGGER 1")
        self.settle(0.20)
        start = time.perf_counter()
        pcm_220 = self.grab(100)
        elapsed = time.perf_counter() - start
        rms_220, _, hz_220 = metrics(pcm_220)
        assert rms_220 > 5_000 and 217 <= hz_220 <= 223
        assert 0.90 <= elapsed <= 1.08, f"unexpected block timing: {elapsed:.3f}s"

        self.send("SET TUNE_HZ 440")
        self.settle(0.20)
        _, _, hz_440 = metrics(self.grab(80))
        assert 435 <= hz_440 <= 445
        print(
            "PACING_TUNE",
            {"100_blocks_seconds": round(elapsed, 3), "hz": [hz_220, hz_440]},
        )

        self.send("TRIGGER 0")
        self.settle(0.05)
        assert metrics(self.grab(10))[0] == 0
        self.send("HOLD 1")
        self.settle(0.10)
        assert metrics(self.grab(10))[0] > 5_000
        self.send("HOLD 0", "SET TUNE_HZ 220", "SET DECAY_MS 300", "TRIGGER 1")
        self.settle(0.10)
        self.send("TRIGGER 0")
        early_decay = metrics(self.grab(10))[0]
        late_decay = metrics(self.grab(60)[-9_600:])[0]
        assert late_decay < early_decay * 0.35
        print("GATE_ENVELOPE", {"early_rms": early_decay, "late_rms": late_decay})

        self.send("SET DECAY_MS 0", "HOLD 1", "SET LFO_DEPTH_OCT 0")
        mode_hashes = {}
        for mode in ("SINE1", "SINE2", "TEST_TONE", "SQUARE",
                     "LICKSHOT", "SONAR"):
            self.send(f"SET MODE {mode}")
            self.settle(0.08)
            mode_hashes[mode] = hashlib.sha256(self.grab(12)).hexdigest()[:12]
        assert len(set(mode_hashes.values())) == 6
        print("MODES", mode_hashes)

        self.send(
            "SET MODE LICKSHOT",
            "SET LFO_SHAPE SAW_DOWN",
            "SET LFO_RATE_HZ 3",
            "SET LFO_DEPTH_OCT 1.2",
            "SET TUNE_HZ 220",
            "MODULATION 1",
            "HOLD 1",
        )
        self.settle(0.20)
        lickshot_pcm = self.grab(100)
        lickshot_frequencies = [
            metrics(lickshot_pcm[index:index + 9_600])[2]
            for index in range(0, len(lickshot_pcm), 9_600)
        ]
        lickshot_rms, lickshot_peak, _ = metrics(lickshot_pcm)
        assert lickshot_rms > 2_000 and lickshot_peak <= 32767
        assert max(lickshot_frequencies) > min(lickshot_frequencies) * 1.5
        self.send("MODULATION 0")
        self.settle(0.25)
        airhorn_pcm = self.grab(60)
        _, airhorn_peak, airhorn_hz = metrics(airhorn_pcm)
        assert 215 <= airhorn_hz <= 225 and airhorn_peak <= 32767
        print("LICKSHOT_AIRHORN", {
            "modulated_hz": lickshot_frequencies,
            "airhorn_hz": airhorn_hz,
        })

        self.send("SET MODE SONAR", "SET LFO_RATE_HZ 1",
                  "SET LFO_DEPTH_OCT 0", "MODULATION 0")
        self.settle(0.20)
        sonar_pcm = self.grab(300)
        sonar_blocks = [metrics(sonar_pcm[i:i + 960])[0]
                        for i in range(0, len(sonar_pcm), 960)]
        pings = sum(rms > 100 and (i == 0 or sonar_blocks[i - 1] <= 100)
                    for i, rms in enumerate(sonar_blocks))
        silent_blocks = sum(rms == 0 for rms in sonar_blocks)
        assert 2 <= pings <= 4 and silent_blocks >= 100
        assert max(sonar_blocks) > 2000 and metrics(sonar_pcm)[1] <= 32767
        print("SONAR", {"pings_3s": pings, "silent_blocks": silent_blocks})

        # Pitch gestures use a continuous voice; Sonar's gaps deliberately
        # invalidate a full-window zero-crossing frequency estimate.
        self.send("SET MODE SINE1", "MODULATION 1")
        self.send("MOD_UP 1", "MOD_DOWN 0")
        self.settle(0.25)
        rise_hz = metrics(self.grab(40))[2]
        self.send("MOD_UP 0", "MOD_DOWN 1")
        self.settle(0.25)
        dive_hz = metrics(self.grab(40))[2]
        self.send("MOD_UP 1")
        self.settle(0.25)
        rise_dive_hz = metrics(self.grab(40))[2]
        assert 430 <= rise_hz <= 450
        assert 105 <= dive_hz <= 115
        assert 215 <= rise_dive_hz <= 225
        self.send("MOD_UP 0", "MOD_DOWN 0")
        print("RISE_DIVE", {"rise_hz": rise_hz, "dive_hz": dive_hz,
                            "both_hz": rise_dive_hz})

        self.send("SET MODE LICKSHOT", "SET LFO_SHAPE SAW_DOWN",
                  "SET LFO_RATE_HZ 2", "SET LFO_DEPTH_OCT 1",
                  "RETRIGGER 1", "HOLD 0", "TRIGGER 0")
        directions = []
        starts = []
        for _ in range(2):
            self.settle(0.08)
            self.send("TRIGGER 1")
            hit = self.grab(30)
            chunks = [
                metrics(hit[index:index + 4_800])[2]
                for index in range(0, len(hit), 4_800)
            ]
            directions.append(chunks[2] - chunks[1])
            starts.append(chunks[1])
            self.send("TRIGGER 0")
        assert directions[0] < 0 and directions[1] < 0
        assert abs(starts[0] - starts[1]) < 35
        self.send("RETRIGGER 0", "HOLD 1")
        print("RETRIGGER", {"start_hz": starts, "direction": directions})

        self.send(
            "SET MODE SINE1",
            "SET LFO_SHAPE MANUAL",
            "SET LFO_DEPTH_OCT 1",
            "SET TUNE_HZ 220",
            "MOD_UP 1",
        )
        self.settle(0.25)
        hz_up = metrics(self.grab(40))[2]
        self.send("MOD_UP 0", "MOD_DOWN 1")
        self.settle(0.25)
        hz_down = metrics(self.grab(40))[2]
        self.send("MOD_UP 1")
        self.settle(0.25)
        hz_both = metrics(self.grab(40))[2]
        assert 430 <= hz_up <= 450
        assert 105 <= hz_down <= 115
        assert 215 <= hz_both <= 225
        self.send("MOD_UP 0", "MOD_DOWN 0")
        print("MANUAL", {"up_hz": hz_up, "down_hz": hz_down, "both_hz": hz_both})

        self.send("SET MODE SINE1", "SET CLASSIC_MOD MANUAL",
                  "SET PROFILE CLASSIC")
        classic_hz = []
        for pitch in ("LOW", "MID", "HIGH"):
            self.send(f"SET CLASSIC_PITCH {pitch}")
            self.settle(0.20)
            classic_hz.append(metrics(self.grab(40))[2])
        assert 105 <= classic_hz[0] <= 115
        assert 215 <= classic_hz[1] <= 225
        assert 430 <= classic_hz[2] <= 450
        self.send("SET PROFILE EXTENDED", "SET LFO_DEPTH_OCT 0",
                  "SET TUNE_HZ 220")
        self.settle(0.20)
        assert 215 <= metrics(self.grab(30))[2] <= 225
        print("CLASSIC_PROFILE", {"low_mid_high_hz": classic_hz,
                                  "extended_restored": True})

        shape_hashes = {}
        self.send("SET LFO_RATE_HZ 8", "SET LFO_DEPTH_OCT 1")
        for shape in (
            "CLASSIC",
            "TRIANGLE",
            "SQUARE",
            "SAW_UP",
            "SAW_DOWN",
            "ASYM_UP",
            "ASYM_DOWN",
            "PULSE_25",
            "PULSE_75",
        ):
            self.send(f"SET LFO_SHAPE {shape}")
            self.settle(0.05)
            shape_hashes[shape] = hashlib.sha256(self.grab(15)).hexdigest()[:12]
        assert len(set(shape_hashes.values())) == 9
        print("LFO_SHAPES", shape_hashes)

        self.send(
            "SET VOICING V2",
            "SET MODE SQUARE",
            "SET TUNE_HZ 220",
            "SET LFO_RATE_HZ 2",
            "SET LFO_DEPTH_OCT 1",
            "SET ECHO_LEVEL 0",
            "HOLD 1",
        )
        self.settle(0.15)
        square_pcm = self.grab(120)
        square_chunks = [
            metrics(square_pcm[index:index + 4_800])[2]
            for index in range(0, len(square_pcm), 4_800)
        ]
        assert min(square_chunks) < 140 and max(square_chunks) > 400
        print("SQUARE_HIGH_LOW", {"min_hz": min(square_chunks),
                                  "max_hz": max(square_chunks)})

        self.send(
            "SET MODE TEST_TONE",
            "SET LFO_RATE_HZ 2",
            "SET LFO_DEPTH_OCT 0",
        )
        self.settle(0.15)
        test_pcm = self.grab(120)
        test_levels = [
            metrics(test_pcm[index:index + 4_800])[0]
            for index in range(0, len(test_pcm), 4_800)
        ]
        assert min(test_levels) < 100 and max(test_levels) > 5_000
        print("TEST_GATE", {"min_rms": min(test_levels),
                            "max_rms": max(test_levels)})

        self.send(
            "SET LFO_DEPTH_OCT 0",
            "SET DELAY_MS 50",
            "SET FEEDBACK 0.90",
            "SET ECHO_LEVEL 1",
            "SET HPF_HZ 50",
            "SET LPF_HZ 19000",
            "SET DECAY_MS 0",
            "HOLD 0",
            "TRIGGER 1",
        )
        self.settle(0.20)
        self.send("TRIGGER 0")
        time.sleep(0.06)
        self.drain()
        wet_rms = metrics(self.grab(10))[0]
        self.send("ECHO_CUT 1")
        self.settle(0.10)
        cut_rms = metrics(self.grab(8))[0]
        self.send("ECHO_CUT 0")
        self.settle(0.10)
        restored_rms = metrics(self.grab(8))[0]
        print("ECHO_CUT", {"wet": wet_rms, "cut": cut_rms, "restored": restored_rms})
        assert wet_rms > 50 and cut_rms == 0 and restored_rms > 10

        self.send("SET FEEDBACK 1.05", "TRIGGER 1")
        self.settle(0.10)
        self.send("TRIGGER 0")
        feedback_pcm = self.grab(150)
        feedback_rms, feedback_peak, _ = metrics(feedback_pcm)
        assert feedback_rms > 10 and feedback_peak <= 32767
        self.send("SET HPF_HZ 7000", "SET LPF_HZ 200")
        filtered = self.grab(30)
        assert hashlib.sha256(filtered).digest() != hashlib.sha256(feedback_pcm[: len(filtered)]).digest()
        print("FEEDBACK_FILTERS", {"rms": feedback_rms, "peak": feedback_peak})

        self.send("SET HPF_HZ 50", "SET LPF_HZ 7000", "SET DELAY_MS 900")
        live_change_pcm = self.grab(40)
        assert hashlib.sha256(live_change_pcm).digest() != hashlib.sha256(
            feedback_pcm[: len(live_change_pcm)]
        ).digest()
        print("DELAY_LIVE_CHANGE", "ok")

        self.send(
            "SET MODE SINE1",
            "SET TUNE_HZ 220",
            "SET LFO_DEPTH_OCT 0",
            "SET DELAY_MS 50",
            "SET FEEDBACK 0.75",
            "SET ECHO_LEVEL 1",
            "SET HPF_HZ 50",
            "SET LPF_HZ 19000",
            "SET DECAY_MS 0",
            "ECHO_LOOP 0",
            "ECHO_CUT 0",
            "HOLD 1",
        )
        self.settle(0.25)
        self.send("HOLD 0", "ECHO_LOOP 1")
        self.settle(0.08)
        loop_pcm = self.grab(100)
        loop_rms, loop_peak, _ = metrics(loop_pcm)
        assert loop_rms > 100 and loop_peak <= 32767
        self.send("ECHO_CUT 1")
        self.settle(0.05)
        assert metrics(self.grab(8))[0] == 0
        self.send("ECHO_CUT 0")
        self.settle(0.05)
        restored_loop_rms = metrics(self.grab(12))[0]
        assert restored_loop_rms > 50
        self.send("ECHO_LOOP 0")
        print("ECHO_LOOP", {"rms": loop_rms, "restored": restored_loop_rms,
                            "peak": loop_peak})

        self.send("SET FEEDBACK 0.4", "HOLD 1", "ECHO_SPIN 1")
        self.settle(0.35)
        spin_pcm = self.grab(80)
        _, spin_peak, _ = metrics(spin_pcm)
        assert spin_peak <= 32767
        self.send("ECHO_SPIN 0", "HOLD 0")
        self.drain()
        spin_release_early = metrics(self.grab(10))[0]
        spin_release_late = metrics(self.grab(60)[-9_600:])[0]
        assert spin_release_late < spin_release_early * 0.7
        print("ECHO_SPIN", {"peak": spin_peak,
                            "release_rms": [spin_release_early,
                                            spin_release_late]})

        self.send("STREAM 0", "HOLD 0", "TRIGGER 0", "ECHO_SPIN 0",
                  "ECHO_LOOP 0", "MOD_UP 0", "MOD_DOWN 0")
        time.sleep(0.15)
        self.drain()
        time.sleep(0.08)
        assert self.audio.empty()
        self.transport.send("UNKNOWN COMMAND")
        self.status_event.clear()
        self.transport.send("HELLO")
        assert self.status_event.wait(1)
        final_status = self.statuses[-1]
        print("RENDER_BUDGET", {
            "last_us": final_status["renderUs"],
            "max_us": final_status["maxRenderUs"],
            "last_cycle_us": final_status["cycleUs"],
            "max_cycle_us": final_status["maxCycleUs"],
            "max_usb_write_us": final_status.get("maxUsbWriteUs"),
            "max_i2s_write_us": final_status.get("maxI2sWriteUs"),
        })
        assert final_status["maxRenderUs"] < 10_000
        assert final_status["maxCycleUs"] < 10_000
        print("STOP_RESYNC", "ok")

    def close(self) -> None:
        try:
            if self.transport.connected:
                self.transport.send("STREAM 0")
        finally:
            self.transport.disconnect()


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("port")
    args = parser.parse_args()
    test = SmokeTest(args.port)
    try:
        test.run()
    finally:
        test.close()


if __name__ == "__main__":
    main()
